"""Generate invented LabSolutions-style result ASCII for exact-profile tests."""

from __future__ import annotations

from collections.abc import Sequence

PEAK_HEADERS = (
    "Peak#",
    "R.Time",
    "I.Time",
    "F.Time",
    "Area",
    "Height",
    "A/H",
    "Conc.",
    "Mark",
    "ID#",
    "Name",
    "k'",
    "Plate #",
    "Plate Ht.",
    "Tailing",
    "Resolution",
    "Sep.Factor",
    "Area Ratio",
    "Height Ratio",
    "Conc. %",
    "Norm Conc.",
)


def _section(name: str, rows: Sequence[str]) -> list[str]:
    return [f"[{name}]", *rows, ""]


def synthetic_result_ascii_bytes(
    *,
    peaks: Sequence[tuple[str, str, str, str, str]] = (
        ("1.25", "100.5", "10.25", "1.20", "1.30"),
        ("2.50", "200.75", "20.5", "2.45", "2.55"),
        ("3.75", "300.0", "30.0", "3.70", "3.80"),
    ),
    application_name: str = "LabSolutions",
    software_version: str = "5.82",
    file_type: str = "Data File",
    instrument_model: str = "GC-2014",
    instrument_number: str = "1",
    line_number: str = "1",
    detector_count: str = "1",
    detector_id: str = "DET#1",
    detector_name: str = "SFID1",
    channel_count: str = "1",
    declared_peak_count: int | None = None,
    id_number: str = "",
    compound_name: str = "",
    chromatogram_rows: Sequence[tuple[str, str]] = (
        ("0.00033", "-1"),
        ("0.00100", "0"),
        ("0.00167", "1"),
        ("0.00233", "2"),
    ),
    declared_point_count: int | None = None,
    interval_ms: str = "40",
    chromatogram_start: str = "0.000",
    chromatogram_end: str = "4.000",
    newline: str = "\r\n",
) -> bytes:
    """Return deterministic invented bytes; no line is copied from a native fixture."""
    lines: list[str] = []
    lines.extend(
        _section(
            "Header",
            (
                f"Application Name\t{application_name}",
                f"Version\t{software_version}",
                "Data File Name\tsynthetic.gcd",
                "Output Date\t2000-01-01",
                "Output Time\t00:00:00",
            ),
        )
    )
    lines.extend(
        _section(
            "File Information",
            (
                f"Type\t{file_type}",
                "Generated\t2000-01-01 00:00:00",
                "Generated by\tsynthetic",
                "Modified\t2000-01-01 00:00:00",
                "Modified by\tsynthetic",
            ),
        )
    )
    sample_rows = [
        "Operator Name\tsynthetic",
        "Acquired\t2000-01-01 00:00:00",
        "Sample Type\tUnknown",
        "Level\t1",
        "Sample Name\tinvented-sample",
        "Sample ID\tSYNTHETIC-001",
        *(f"ISTD Amount{index}\t0.000" for index in range(1, 33)),
        "Sample Amount\t1.000",
        "Dilution Factor\t1.000",
        "Vial#\t1",
        "Injection Volume\t1.000",
        "Injection Count\t1",
        "Bar Code\t",
    ]
    lines.extend(_section("Sample Information", sample_rows))
    lines.extend(
        _section(
            "Original Files",
            (
                "Data File\tsynthetic.gcd",
                "Method File\tsynthetic.gcm",
                "Batch File\tsynthetic.gcb",
                "Report Format File\tsynthetic.lsr",
            ),
        )
    )
    lines.extend(_section("File Description", ("Invented synthetic fixture",)))
    lines.extend(
        _section(
            "Configuration",
            (
                f"Instrument Name\t{instrument_model}",
                f"Instrument #\t{instrument_number}",
                f"Line #\t{line_number}",
                f"# of Detectors\t{detector_count}",
                f"Detector ID\t{detector_id}",
                f"Detector Name\t{detector_name}",
                f"# of Channels\t{channel_count}",
            ),
        )
    )
    count = len(peaks) if declared_peak_count is None else declared_peak_count
    peak_rows = [f"# of Peaks\t{count}", "\t".join(PEAK_HEADERS)]
    for index, (retention, area, height, start, end) in enumerate(peaks, start=1):
        peak_rows.append(
            "\t".join(
                (
                    str(index),
                    retention,
                    start,
                    end,
                    area,
                    height,
                    "1.000",
                    "0.000",
                    " V ",
                    id_number,
                    compound_name,
                    "0.000",
                    "1",
                    "1.000",
                    "0.000",
                    "0.000",
                    "0.000",
                    "0",
                    "0",
                    "0.000",
                    "0.000",
                )
            )
        )
    lines.extend(_section("Peak Table(Ch1)", peak_rows))
    lines.extend(_section("Compound Results(Ch1)", ("# of IDs\t0",)))
    point_count = len(chromatogram_rows) if declared_point_count is None else declared_point_count
    chromatogram = [
        f"Interval(msec)\t{interval_ms}",
        f"# of Points\t{point_count}",
        f"Start Time(min)\t{chromatogram_start}",
        f"End Time(min)\t{chromatogram_end}",
        "R.Time (min)\tIntensity",
        *(f"{time}\t{intensity}" for time, intensity in chromatogram_rows),
    ]
    lines.extend(_section("Chromatogram (Ch1)", chromatogram))
    return (newline.join(lines) + newline).encode("ascii")
